translate the question "Show the name and theme for all concerts and the number of singers in each concert." into SPARQL.

execution_result.cleaned_query:
SELECT ?concert_name ?theme (COUNT(?singer_id) AS ?number_of_singers)
WHERE {
  ?concert a :concert .
  ?concert :concert\#concert_name ?concert_name .
  ?concert :concert\#theme ?theme .
  OPTIONAL {
    ?singer_in_concert a :singer_in_concert .
    ?singer_in_concert :singer_in_concert\#ref-concert_id ?concert .
    ?singer_in_concert :singer_in_concert\#singer_id ?singer_id .
  }
}
GROUP BY ?concert_name ?theme

